587	// ---------------------------------------------------------------------------
588	// 离线兼容报告（compare 子命令）
589	// ---------------------------------------------------------------------------
590	//
591	// 兼容方向固定为 旧 -> 新：旧配置能按“方法 + 字面路径”匹配且通过正文检查的
592	// 每一种请求，在新配置中仍须匹配并通过。只比较接口存在性与请求接受条件；
593	// 响应状态/头/正文/延迟与序列差异不影响结论。
594	//
595	// 双方都配置 requestBody 时，比较的是“规则所接受 JSON 值的集合包含关系”
596	// L(旧规则) ⊆ L(新规则)，而不是文本比较或抽样请求；每个不兼容点都附一份
597	// 具体反例（旧规则接受、新规则拒绝的完整 JSON 值）。
598	
599	interface ReportReason {
600	  // 正文差异：RFC 6901 指针（根为 ""）；接口级原因（如接口删除）无此字段
601	  readonly pointer?: string;
602	  readonly message: string;
603	}
604	
605	interface ReportExample {
606	  readonly method: HttpMethod;
607	  readonly path: string;
608	  readonly headers: { readonly [name: string]: string };
609	  readonly body: string;
610	}
611	
612	interface EndpointReport {
613	  readonly method: HttpMethod;
614	  readonly path: string;
615	  readonly compatible: boolean;
616	  readonly reasons: readonly ReportReason[];
617	  readonly example?: ReportExample;
618	}
619	
620	interface CompareReport {
621	  readonly compatible: boolean;
622	  readonly oldFile: string;
623	  readonly newFile: string;
624	  readonly endpoints: readonly EndpointReport[];
625	}
626	
627	interface BodyViolation {
628	  readonly pointer: string;
629	  readonly message: string;
630	  // 完整请求正文反例：被旧规则接受、被新规则拒绝
631	  readonly value: unknown;
632	}
633	
634	// 生成被规则接受的最小 JSON 值：object 只含必填字段，array 取空数组。
635	// 字段名可能是 "" 或 "__proto__"，一律用无原型对象按自有字段构造。
636	function sampleValue(rule: BodyRule): unknown {
637	  switch (rule.kind) {
638	    case 'string':
639	      return 'contractlab';
640	    case 'number':
641	    case 'integer':
642	      return 0;
643	    case 'boolean':
644	      return false;
645	    case 'null':
646	      return null;
647	    case 'array':
648	      return [];
649	    case 'object': {
650	      const obj: Record<string, unknown> = Object.create(null);
651	      for (const [name, field] of rule.fields) {
652	        if (field.required) {
653	          obj[name] = sampleValue(field.rule);
654	        }
655	      }
656	      return obj;
657	    }
658	  }
659	}
660	
661	// 在 object 规则的最小样本上补一个字段（字段值本身须被该字段规则接受）
662	function sampleObjectWith(
663	  rule: Extract<BodyRule, { kind: 'object' }>,
664	  name: string,
665	  value: unknown,
666	): Record<string, unknown> {
667	  const obj = sampleValue(rule) as Record<string, unknown>;
668	  obj[name] = value;
669	  return obj;
670	}
671	
672	// 生成被规则拒绝的 JSON 值（顶层类型即不符；任何规则都存在这样的值）
673	function violateValue(rule: BodyRule): unknown {
674	  switch (rule.kind) {
675	    case 'number':
676	      return 'contractlab'; // 非数字
677	    case 'integer':
678	      return 0.5; // 非整数
679	    default:
680	      return 0; // 非 string / boolean / null / object / array
681	  }
682	}
683	
684	function kindLabel(rule: BodyRule): string {
685	  if (rule.kind === 'object') {
686	    return rule.additionalProperties ? 'object（允许未声明字段）' : 'object（拒绝未声明字段）';
687	  }
688	  return rule.kind;
689	}
690	
691	// 选一个两个规则都未声明的字段名，用于构造“额外字段”反例
692	function freshFieldName(
693	  oldFields: ReadonlyMap<string, FieldRule>,
694	  newFields: ReadonlyMap<string, FieldRule>,
695	): string {
696	  for (let i = 0; ; i += 1) {
697	    const name = i === 0 ? 'extra' : `extra_${i}`;
698	    if (!oldFields.has(name) && !newFields.has(name)) {
699	      return name;
700	    }
701	  }
702	}
703	
704	// 递归判定 L(oldRule) ⊆ L(newRule)；把发现的每个反例（连同完整正文样本）推入 out。
705	// 不变式：value 必被 oldRule 接受、被 newRule 拒绝；pointer 用 RFC 6901 定位差异。
706	function collectViolations(
707	  oldRule: BodyRule,
708	  newRule: BodyRule,
709	  pointer: string,
710	  out: BodyViolation[],
711	): void {
712	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
713	    // 标量：仅同名兼容，外加 integer 放宽为 number；其余组合两集合相交为空或有差异
714	    const compatible =
715	      oldRule.kind === newRule.kind || (oldRule.kind === 'integer' && newRule.kind === 'number');
716	    if (!compatible) {
717	      // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
718	      const value =
719	        oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
720	      out.push({
721	        pointer,
722	        value,
723	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
724	      });
725	    }
726	    return;
727	  }
728	
729	  if (newRule.kind === 'array') {
730	    if (oldRule.kind !== 'array') {
731	      out.push({
732	        pointer,
733	        value: sampleValue(oldRule),
734	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
735	      });
736	      return;
737	    }
738	    // 元素规则收紧：用非空数组 [反例] 体现（空数组双方都会接受）
739	    const sub: BodyViolation[] = [];
740	    collectViolations(oldRule.items, newRule.items, `${pointer}/0`, sub);
741	    for (const s of sub) {
742	      out.push({ pointer: s.pointer, message: s.message, value: [s.value] });
743	    }
744	    return;
745	  }
746	
747	  // newRule.kind === 'object'
748	  if (oldRule.kind !== 'object') {
749	    out.push({
750	      pointer,
751	      value: sampleValue(oldRule),
752	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
753	    });
754	    return;
755	  }
756	
757	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
758	  for (const [name, newField] of newRule.fields) {
759	    if (!newField.required) {
760	      continue;
761	    }
762	    const oldField = oldRule.fields.get(name);
763	    if (!oldField || !oldField.required) {
764	      out.push({
765	        pointer: `${pointer}/${escapePointerSegment(name)}`,
766	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
767	        value: sampleValue(oldRule),
768	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
769	      });
770	    }
771	  }
772	
773	  // (b) 旧规则声明的字段，在新规则下仍须被接受
774	  for (const [name, oldField] of oldRule.fields) {
775	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
776	    const newField = newRule.fields.get(name);
777	    if (!newField) {
778	      if (!newRule.additionalProperties) {
779	        out.push({
780	          pointer: childPointer,
781	          value: sampleObjectWith(oldRule, name, sampleValue(oldField.rule)),
782	          message: `新规则拒绝旧规则允许的字段 ${JSON.stringify(name)}（新规则未声明且 additionalProperties 为 false）`,
783	        });
784	      }
785	      continue;
786	    }
787	    const sub: BodyViolation[] = [];
788	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
789	    for (const s of sub) {
790	      out.push({
791	        pointer: s.pointer,
792	        message: s.message,
793	        value: sampleObjectWith(oldRule, name, s.value),
794	      });
795	    }
796	  }
797	
798	  // (c) 旧规则允许未声明的额外字段时，新规则必须同样放行这些字段
799	  if (oldRule.additionalProperties) {
800	    if (!newRule.additionalProperties) {
801	      const name = freshFieldName(oldRule.fields, newRule.fields);
802	      out.push({
803	        pointer: `${pointer}/${escapePointerSegment(name)}`,
804	        value: sampleObjectWith(oldRule, name, 0),
805	        message: '旧规则允许未声明的额外字段，新规则拒绝（additionalProperties 为 false）',
806	      });
807	    } else {
808	      // 新规则虽放行额外字段，但其新声明的字段会约束旧版原本自由的取值
809	      for (const [name, newField] of newRule.fields) {
810	        if (oldRule.fields.has(name)) {
811	          continue;
812	        }
813	        out.push({
814	          pointer: `${pointer}/${escapePointerSegment(name)}`,
815	          value: sampleObjectWith(oldRule, name, violateValue(newField.rule)),
816	          message: `旧规则对额外字段 ${JSON.stringify(name)} 不限制取值，新规则要求其为 ${kindLabel(newField.rule)}`,
817	        });
818	      }
819	    }
820	  }
821	}
822	
823	// 旧接口被旧配置接受的一个请求样本（用于“接口已删除”反例）
824	function acceptedRequestExample(endpoint: EndpointSpec): ReportExample {
825	  if (endpoint.bodyRule) {
826	    return {
827	      method: endpoint.method,
828	      path: endpoint.path,
829	      headers: { 'Content-Type': 'application/json' },
830	      body: JSON.stringify(sampleValue(endpoint.bodyRule)),
831	    };
832	  }
833	  return { method: endpoint.method, path: endpoint.path, headers: {}, body: '' };
834	}
835	
836	function compareEndpoint(oldEp: EndpointSpec, newEp: EndpointSpec | undefined): EndpointReport {
837	  const base = { method: oldEp.method, path: oldEp.path };
838	
839	  if (!newEp) {
840	    return {
841	      ...base,
842	      compatible: false,
843	      reasons: [
844	        { message: '新配置中不存在该接口：按 方法 + 字面路径 匹配不到，旧客户端的调用将得到 404' },
845	      ],
846	      example: acceptedRequestExample(oldEp),
847	    };
848	  }
849	
850	  if (!oldEp.bodyRule && !newEp.bodyRule) {
851	    return { ...base, compatible: true, reasons: [] };
852	  }
853	
854	  if (!oldEp.bodyRule && newEp.bodyRule) {
855	    // 旧版允许任意媒体类型与正文；新版启用校验即存在被拒绝的旧请求
856	    return {
857	      ...base,
858	      compatible: false,
859	      reasons: [
860	        {
861	          pointer: '',
862	          message: '旧接口不校验请求正文（任意媒体类型与正文均可），新接口启用了 requestBody 正文校验',
863	        },
864	      ],
865	      example: {
866	        ...base,
867	        headers: { 'Content-Type': 'application/json' },
868	        body: JSON.stringify(violateValue(newEp.bodyRule)),
869	      },
870	    };
871	  }
872	
873	  if (oldEp.bodyRule && !newEp.bodyRule) {
874	    return { ...base, compatible: true, reasons: [] }; // 移除规则更宽松
875	  }
876	
877	  const violations: BodyViolation[] = [];
878	  collectViolations(oldEp.bodyRule as BodyRule, newEp.bodyRule as BodyRule, '', violations);
879	  if (violations.length === 0) {
880	    return { ...base, compatible: true, reasons: [] };
881	  }
882	  return {
883	    ...base,
884	    compatible: false,
885	    reasons: violations.map((v) => ({ pointer: v.pointer, message: v.message })),
886	    example: {
887	      ...base,
888	      headers: { 'Content-Type': 'application/json' },
889	      body: JSON.stringify(violations[0].value),
890	    },
891	  };
892	}
893	
894	function compareConfigs(
895	  oldSpecs: readonly EndpointSpec[],
896	  newSpecs: readonly EndpointSpec[],
897	  oldFile: string,
898	  newFile: string,
899	): CompareReport {
900	  const newByKey = new Map<string, EndpointSpec>();
901	  for (const spec of newSpecs) {
902	    newByKey.set(`${spec.method} ${spec.path}`, spec);
903	  }
904	  const endpoints = oldSpecs.map((spec) =>
905	    compareEndpoint(spec, newByKey.get(`${spec.method} ${spec.path}`)),
906	  );
907	  return {
908	    compatible: endpoints.every((ep) => ep.compatible),
909	    oldFile,
910	    newFile,
911	    endpoints,
912	  };
913	}
914	
915	async function runCompare(oldArg: string, newArg: string): Promise<never> {
916	  const oldFile = path.resolve(oldArg);
917	  const newFile = path.resolve(newArg);
918	
919	  const attempt = async (
920	    file: string,
921	  ): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
922	    try {
923	      return { specs: await loadSpecsFromFile(file) };
924	    } catch (e) {
925	      return { error: describeError(e) };
926	    }
927	  };
928	
929	  // 两份文件都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
930	  const [oldResult, newResult] = await Promise.all([attempt(oldFile), attempt(newFile)]);
931	  let failed = false;
932	  if (oldResult.error !== undefined) {
933	    process.stderr.write(`${APP_NAME}: compare 旧文件：${oldResult.error}\n`);
934	    failed = true;
935	  }
936	  if (newResult.error !== undefined) {
937	    process.stderr.write(`${APP_NAME}: compare 新文件：${newResult.error}\n`);
938	    failed = true;
939	  }
940	  if (failed) {
941	    process.exit(2);
942	  }
943	
944	  const report = compareConfigs(
945	    oldResult.specs as EndpointSpec[],
946	    newResult.specs as EndpointSpec[],
947	    oldFile,
948	    newFile,
949	  );
950	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
951	  process.exit(report.compatible ? 0 : 1);
952	}
