958	
959	// 模块级运行时句柄（启动后赋值）
960	let activeState: LiveState;
961	let server: http.Server;
962	let configFile = '';
963	let shuttingDown = false;
964	
965	// 尚未发出的延迟响应定时器，关闭时统一取消
966	const pendingTimers = new Set<ReturnType<typeof setTimeout>>();
967	
968	// 重载按“触发顺序”串行处理：后一个 reload 必定在前一个落定后才读文件
969	let reloadChain: Promise<unknown> = Promise.resolve();
970	
971	function triggerReload(): Promise<ReloadResult> {
972	  const job = reloadChain.then(async (): Promise<ReloadResult> => {
973	    try {
974	      // 校验通过前只构造局部变量，任何失败都不会触碰 activeState
975	      const next = await loadStateFromFile(configFile, activeState.version + 1);
976	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
977	      return { ok: true, version: activeState.version };
978	    } catch (e) {
979	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
980	      return { ok: false, version: activeState.version, error: describeError(e) };
981	    }
982	  });
983	  // 失败也不能打断后续 reload 的排队
984	  reloadChain = job.then(
985	    () => undefined,
986	    () => undefined,
987	  );
988	  return job;
989	}
990	
991	function writeResponse(
992	  res: http.ServerResponse,
993	  status: number,
994	  headers: { readonly [name: string]: string },
995	  body: string,
996	): void {
997	  try {
998	    res.writeHead(status, headers);
999	    res.end(body === '' ? undefined : body);
1000	  } catch {
1001	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
1002	  }
1003	}
1004	
1005	function versionHeaders(
1006	  version: number,
1007	  extra?: { readonly [name: string]: string },
1008	): { [name: string]: string } {
1009	  // 无原型对象：配置中名为 "__proto__" 的响应头在合并时不丢失
1010	  const headers: { [name: string]: string } = Object.create(null);
1011	  headers[VERSION_HEADER] = String(version);
1012	  if (extra) {
1013	    for (const [name, value] of Object.entries(extra)) {
1014	      headers[name] = value;
1015	    }
1016	  }
1017	  return headers;
1018	}
1019	
1020	function sendJson(res: http.ServerResponse, status: number, value: unknown, version: number): void {
1021	  writeResponse(
1022	    res,
1023	    status,
1024	    versionHeaders(version, { 'Content-Type': 'application/json; charset=utf-8' }),
1025	    `${JSON.stringify(value)}\n`,
1026	  );
1027	}
1028	
1029	function sendNotFound(res: http.ServerResponse): void {
1030	  writeResponse(
1031	    res,
1032	    404,
1033	    versionHeaders(activeState.version, {
1034	      'Content-Type': 'text/plain; charset=utf-8',
1035	    }),
1036	    'not found\n',
1037	  );
1038	}
1039	
1040	function sendBusinessResponse(
1041	  res: http.ServerResponse,
1042	  item: ResponseSpec,
1043	  version: number,
1044	): void {
1045	  const headers = versionHeaders(version);
1046	  let contentTypeSet = false;
1047	  for (const [name, value] of Object.entries(item.headers)) {
1048	    const lower = name.toLowerCase();
1049	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
1050	    if (lower === VERSION_HEADER.toLowerCase()) {
1051	      continue;
1052	    }
1053	    if (lower === 'content-type') {
1054	      contentTypeSet = true;
1055	    }
1056	    headers[name] = value;
1057	  }
1058	  // 文本正文的默认内容类型；配置显式给出时不覆盖
1059	  if (!contentTypeSet && item.body !== '') {
1060	    headers['Content-Type'] = 'text/plain; charset=utf-8';
1061	  }
1062	  writeResponse(res, item.status, headers, item.body);
1063	}
1064	
1065	// 延迟结束才发送；即便客户端提前断开也继续计时（消费在预留时已经成立）
1066	function scheduleBusinessResponse(
1067	  res: http.ServerResponse,
1068	  item: ResponseSpec,
1069	  version: number,
1070	): void {
1071	  const timer = setTimeout(() => {
1072	    pendingTimers.delete(timer);
1073	    sendBusinessResponse(res, item, version);
1074	  }, item.delay);
1075	  pendingTimers.add(timer);
1076	}
1077	
1078	type BodyOutcome = 'received' | 'aborted' | 'too-large';
1079	
1080	interface ReceivedBody {
1081	  readonly outcome: BodyOutcome;
1082	  // 仅在 outcome 为 'received' 时有意义（完整请求体）
1083	  readonly body: Buffer;
1084	}
1085	
1086	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
1087	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
1088	  return new Promise((resolve) => {
1089	    let settled = false;
1090	    let size = 0;
1091	    const chunks: Buffer[] = [];
1092	    const finish = (outcome: BodyOutcome): void => {
1093	      if (!settled) {
1094	        settled = true;
1095	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
1096	      }
1097	    };
1098	    req.on('data', (chunk: Buffer) => {
1099	      size += chunk.byteLength;
1100	      if (size > MAX_BODY_BYTES) {
1101	        finish('too-large');
1102	        writeResponse(
1103	          res,
1104	          413,
1105	          versionHeaders(activeState.version, {
1106	            'Content-Type': 'text/plain; charset=utf-8',
1107	          }),
1108	          'payload too large\n',
1109	        );
1110	        // 等 413 刷出后再断开，避免客户端收不到响应
1111	        res.once('finish', () => req.socket.destroy());
1112	        return;
1113	      }
1114	      chunks.push(chunk);
1115	    });
1116	    req.on('end', () => finish('received'));
1117	    req.on('error', () => finish('aborted'));
1118	    req.on('aborted', () => finish('aborted'));
1119	    res.on('close', () => finish('aborted'));
1120	  });
1121	}
1122	
1123	async function dispatch(
1124	  req: http.IncomingMessage,
1125	  res: http.ServerResponse,
1126	): Promise<void> {
1127	  res.on('error', () => {
1128	    // 写已销毁套接字等错误无需让进程崩溃
1129	  });
1130	
1131	  const { outcome, body } = await receiveBody(req, res);
1132	  if (outcome !== 'received') {
1133	    // aborted：未完整接收，不匹配、不预留、不推进任何序列
1134	    // too-large：已回复 413
1135	    return;
1136	  }
1137	
1138	  const method = String(req.method);
1139	  const pathname = String(req.url ?? '/').split('?')[0]; // 查询串不参与匹配
1140	
1141	  // 管理入口（不消费任何业务序列）
1142	  if (pathname === HEALTH_PATH) {
1143	    if (method === 'GET') {
1144	      sendJson(res, 200, { status: 'ok', version: activeState.version }, activeState.version);
1145	    } else {
1146	      sendNotFound(res);
1147	    }
1148	    return;
1149	  }
1150	
1151	  if (pathname === RELOAD_PATH) {
1152	    if (method === 'POST') {
1153	      const result = await triggerReload();
1154	      sendJson(res, 200, result, result.version);
1155	    } else {
1156	      sendNotFound(res);
1157	    }
1158	    return;
1159	  }
1160	
1161	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
1162	  const state = activeState;
1163	  const endpoint =
1164	    method === 'GET' || method === 'POST'
1165	      ? state.endpoints.get(`${method} ${pathname}`)
1166	      : undefined;
1167	
1168	  if (!endpoint) {
1169	    sendNotFound(res); // 未匹配请求：404，不消费
1170	    return;
1171	  }
1172	
1173	  // 正文结构规则（如有）：校验失败返回 400 差异报告，不发送场景响应、不消费序列。
1174	  // 规则、序列与版本均取自上面同一快照 state。
1175	  if (endpoint.bodyRule) {
1176	    const report = validateRequestBody(req, body, endpoint.bodyRule);
1177	    if (report) {
1178	      sendJson(res, 400, report, state.version);
1179	      return;
1180	    }
1181	  }
1182	
1183	  const item = reserveNext(endpoint); // 校验通过后立即预留
1184	  scheduleBusinessResponse(res, item, state.version);
1185	}
