1217	  server = http.createServer((req, res) => {
1218	    dispatch(req, res).catch(() => {
1219	      try {
1220	        req.socket.destroy();
1221	      } catch {
1222	        // 套接字可能已销毁
1223	      }
1224	    });
1225	  });
1226	
1227	  await new Promise<void>((resolve, reject) => {
1228	    server.once('error', reject);
1229	    // 仅监听本机回环地址
1230	    server.listen(port, '127.0.0.1', resolve);
1231	  });
