1235	  process.stdout.write(
1236	    `${APP_NAME}: listening on http://127.0.0.1:${actualPort}\n` +
1237	      `${APP_NAME}: config ${configFile} (version 1, ${activeState.endpoints.size} endpoints)\n`,
1238	  );
